SELECT p.gender, CAST(COUNT(CASE WHEN a.dischtime IS NOT NULL THEN 1 END) AS FLOAT) / NULLIF(COUNT(a.hadm_id), 0) AS alive_to_dead_ratio, COUNT(CASE WHEN a.dischtime IS NULL THEN 1 END) AS dead_count, percent_rank() OVER (ORDER BY a.los) AS percentile_rank FROM patients p JOIN admissions a ON p.subject_id = a.subject_id WHERE p.gender = 'M' AND EXTRACT(YEAR FROM age(CURRENT_DATE, p.dob)) = 72 AND a.admittime BETWEEN '2015-01-01' AND '2018-12-31' AND a.edregtime BETWEEN '2015-01-01' AND '2018-12-31' AND (a.dischtime - a.admittime) >= 7 AND (a.dischtime - a.admittime) <= 14 GROUP BY p.gender;